/** Server-side Review authoring. Keys are explicit activity IDs; a shared
 * workbench or a matching word never enables a rubric on its own. Each unit
 * asks for a causal explanation and a discriminating counterexample. */
export type ReviewQuestion = [prompt: string, supported: string, contradiction: string, irrelevant: string, alternativeSupported?: string];
export type ReviewUnit = { criterion: string; questions: ReviewQuestion[] };
const unit = (criterion: string, ...questions: ReviewQuestion[]): ReviewUnit => ({ criterion, questions });
